import { defineConfig, type ViteUserConfig } from 'vitest/config'

/**
 * The coverage standard for every package: 90 % of lines, statements, functions and branches
 * of everything under `src/`, untested files included (they count as 0 %).
 */
export const coverage = {
  provider: 'v8',
  include: ['src/**/*.{ts,tsx}'],
  exclude: [
    // Tests and their helpers are not the code under test.
    '**/*.test.{ts,tsx}',
    'src/test/**',
    // Generated by `prisma generate`.
    'src/generated/**',
    '**/*.d.ts',
  ],
  thresholds: { lines: 90, statements: 90, functions: 90, branches: 90 },
  reporter: ['text-summary', ['text', { skipFull: true }], 'html'],
  reportsDirectory: 'coverage',
} satisfies NonNullable<NonNullable<ViteUserConfig['test']>['coverage']>

/** Pure TypeScript packages. */
export function node(overrides: ViteUserConfig = {}) {
  return defineConfig({
    ...overrides,
    test: {
      environment: 'node',
      include: ['src/**/*.test.ts'],
      exclude: ['**/*.integration.test.ts', '**/node_modules/**'],
      // Nothing one test set up leaks into the next.
      restoreMocks: true,
      coverage,
      ...overrides.test,
    },
  })
}
